
.track {
  display: flex;
  flex-direction: column;
  gap: 7px;
  min-width: 0;
}

.track__title {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.16em;
  color: var(--c-primary);
  padding-bottom: 5px;
  border-bottom: 1px solid var(--c-border);
}

.field {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}

.field__key {
  flex: none;
  font-size: 11px;
  letter-spacing: 0.06em;
  color: var(--c-text-muted);
}

.field__value {
  font-size: 12px;
  color: var(--c-text);
  overflow-wrap: anywhere;
}

.field__value--mono {
  font-family: var(--font-mono);
  letter-spacing: 0.02em;
}

.affairs {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}

.affairs__list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.affairs__item {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding-left: 7px;
  border-left: 1px solid var(--c-border);
}

.affairs__name {
  font-size: 12px;
  color: var(--c-text);
}

.affairs__progress {
  font-size: 11px;
  color: var(--c-text-muted);
  overflow-wrap: anywhere;
}

.affairs__empty {
  font-size: 12px;
  color: var(--c-text-muted);
}
