
.rope {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 12px;
  height: 12px;
  opacity: 0;
  transition:
    opacity 0.8s ease,
    transform 0.8s ease;
}

.rope--stirred {
  opacity: 1;
}

.rope__knot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--c-accent);
  box-shadow: 0 0 5px var(--c-accent);
  animation: rope-pulse 3.2s ease-in-out infinite;
}

@keyframes rope-pulse {
  0%,
  100% {
    transform: scale(1);
    opacity: 0.75;
  }

  50% {
    transform: scale(1.18);
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .rope__knot {
    animation: none;
  }
}
